<script setup lang="ts">
import { computed, ref } from 'vue'
import { use } from 'echarts/core'
import { CanvasRenderer } from 'echarts/renderers'
import { LineChart, BarChart } from 'echarts/charts'
import { GridComponent, TooltipComponent, LegendComponent, DataZoomComponent, GraphicComponent } from 'echarts/components'
import { ElTable, ElTableColumn, ElTag } from 'element-plus'
import VChart from 'vue-echarts'
import { trendOption, comparisonOption, rankingOption, metricUnit, type OperatingData } from './operatingCharts'
use([CanvasRenderer, LineChart, BarChart, GridComponent, TooltipComponent, LegendComponent, DataZoomComponent, GraphicComponent])
const props = defineProps<{ message: OperatingData; metrics: OperatingData; compact?: boolean }>()
const showCharts = ref(!props.compact || !!props.message.report)
const evidence = computed(() => props.message.evidence)
const report = computed(() => props.message.report)
const metric = computed(() => evidence.value?.filters.metric || 'revenue')
const label = computed(() => props.metrics[metric.value] || '成交金额')
const format = (v: any) => v == null ? '—' : Number(v).toLocaleString('zh-CN', { maximumFractionDigits: 2 })
const percent = (v: any) => v == null ? '不可比' : `${v > 0 ? '+' : ''}${(v * 100).toFixed(2)}%`
const narrative = computed(() => props.message.narrative || { analysis: props.message.answer.split('分析与建议：').at(-1), hypotheses: [], actions: [] })
const comparisons = computed(() => !evidence.value ? [] : ['yoy', 'mom'].map(key => ({ key, name: key === 'yoy' ? '去年同期' : '上月同期', ...evidence.value.comparisons[key] })))
const queryResults = computed(() => evidence.value?.query_results || [])
function reportChartOption(chart: OperatingData) {
  const result = queryResults.value.find((q: OperatingData) => q.id === chart.query_id)
  if (!result) return {}
  const unit = result.unit || ''
  const ratio = ['conversion', 'cart_rate'].includes(result.spec?.metric)
  const chartValue = (value: any) => value == null ? null : ratio ? Number(value) * 100 : Number(value)
  const valueLabel = (value: any) => ratio ? `${Number(value).toFixed(2)}%` : Number(value).toLocaleString('zh-CN', { maximumFractionDigits: 2 })
  const axisLabel = (value: number) => ratio ? `${Number(value).toFixed(2)}%` : Number(value).toLocaleString('zh-CN', { notation: 'compact' })
  const tooltip = { trigger: 'axis', renderMode: 'html', valueFormatter: valueLabel }
  if (chart.type === 'comparison') {
    const entries = [{ name: '本期', value: result.value }, ...Object.entries(result.comparisons || {}).map(([key, value]: any) => ({ name: key === 'yoy' ? '去年同期' : key === 'yoy2' ? '前年同期' : '上月同期', value: value.selected_value }))]
    return { tooltip, grid: { left: 78, right: 28, top: 30, bottom: 40 }, xAxis: { type: 'category', data: entries.map(e => e.name) }, yAxis: { type: 'value', name: unit, axisLabel: { formatter: axisLabel } }, series: [{ type: 'bar', barMaxWidth: 50, data: entries.map((e, i) => ({ value: chartValue(e.value), itemStyle: { color: i ? '#93c5fd' : '#0f766e', borderRadius: [5, 5, 0, 0] } })) }] }
  }
  const rows = chart.type === 'ranking' ? result.rows.slice(0, 10) : result.rows
  if (chart.type === 'ranking') return { tooltip, grid: { left: 200, right: 80, top: 20, bottom: 40 }, xAxis: { type: 'value', name: unit, axisLabel: { formatter: axisLabel } }, yAxis: { type: 'category', inverse: true, data: rows.map((r: OperatingData) => `${r.name || r.label}${r.code ? `\n${r.code}` : ''}`), axisLabel: { formatter: (v: string) => v.split('\n').map(x => x.length > 16 ? x.slice(0, 16) + '…' : x).join('\n'), lineHeight: 18 } }, series: [{ type: 'bar', barMaxWidth: 23, data: rows.map((r: OperatingData, i: number) => ({ value: chartValue(r.value), itemStyle: { color: i < 3 ? '#0f766e' : '#93c5fd', borderRadius: [0, 5, 5, 0] } })) }] }
  return { tooltip, grid: { left: 78, right: 28, top: 28, bottom: 65 }, xAxis: { type: 'category', data: rows.map((r: OperatingData) => r.label), axisLabel: { formatter: (v: string) => v.slice(5) } }, yAxis: { type: 'value', name: unit, axisLabel: { formatter: axisLabel } }, dataZoom: [{ type: 'inside' }, { type: 'slider', height: 16, bottom: 12 }], series: [{ type: 'line', showSymbol: rows.length < 40, smooth: true, areaStyle: { opacity: .07 }, lineStyle: { width: 3 }, data: rows.map((r: OperatingData) => chartValue(r.value)) }] }
}
</script>

<template>
  <article class="response" :class="{ compact }">
    <div v-if="!compact" class="question"><span class="avatar user">问</span><h3>{{ message.question }}</h3></div>
    <div class="response-head"><span class="avatar">AI</span><strong>经营分析助手</strong><el-tag v-if="evidence" type="success" size="small">已查询真实数据</el-tag></div>
    <template v-if="report">
      <p class="understood">问题理解：{{ report.understood_as }}</p>
      <div v-if="report.highlights?.length" class="report-highlights"><article v-for="(card, i) in report.highlights" :key="i"><span>{{ card.label }}</span><strong>{{ card.value }}</strong><small>{{ card.note }}</small></article></div>
      <section v-for="(section, i) in report.sections" :key="i" class="report-section" :class="{ direct: i === 0 }"><h4>{{ section.title }}</h4><p v-for="(p, j) in section.paragraphs" :key="`p${j}`">{{ p }}</p><ul v-if="section.bullets.length"><li v-for="(b, j) in section.bullets" :key="`b${j}`">{{ b }}</li></ul></section>
      <button v-if="report.charts?.length" class="chart-toggle" @click="showCharts = !showCharts">{{ showCharts ? '收起数据图表' : `查看数据图表（${report.charts.length}）` }}</button>
      <div v-if="showCharts && report.charts?.length" class="report-charts"><section v-for="chart in report.charts" :key="`${chart.query_id}-${chart.type}`"><h4>{{ chart.title }}</h4><VChart :option="reportChartOption(chart)" autoresize class="chart" /></section></div>
      <details v-if="report.tables?.length" class="report-tables"><summary>查看数据表与贡献明细</summary><section v-for="(table, i) in report.tables" :key="i"><h4>{{ table.title }}<small v-if="table.total_rows > table.rows.length">展示 {{ table.rows.length }} / {{ table.total_rows }} 条关键记录</small></h4><el-table :data="table.rows" stripe max-height="420"><el-table-column v-for="column in table.columns" :key="column.key" :prop="column.key" :label="column.label" min-width="145" show-overflow-tooltip /></el-table></section></details>
      <section v-if="report.limitations?.length" class="limitations"><h4>口径与限制</h4><ul><li v-for="(item, i) in report.limitations" :key="i">{{ item }}</li></ul></section>
      <section v-if="report.knowledge_sources?.length" class="knowledge-sources"><h4>知识来源</h4><a v-for="source in report.knowledge_sources" :key="source.id" :href="source.url" target="_blank" rel="noopener"><strong>{{ source.title }} · {{ source.heading }}</strong><span>{{ source.location }} · 版本 {{ source.digest }}</span><p>{{ source.excerpt }}</p></a></section>
      <details class="answer-audit"><summary>回答依据与完整性核对</summary><p>回答目标：{{ report.audit.answer_requirements.join('；') }}</p><p v-if="report.audit.mode === 'deterministic'">本回答由服务端确定性查询生成，查询对象、统计期间和同期口径均已校验。</p><p v-else-if="report.audit.review">相关性、完整性、数据依据和行动有效性均通过回答审查。</p><p v-else>模型审查暂时不可用；数值仍经过服务端计算和事实占位校验。</p></details>
    </template>
    <template v-else-if="evidence && evidence.summary.row_count">
      <p class="response-scope">{{ evidence.filters.start }} 至 {{ evidence.filters.end }} · {{ evidence.filters.brand || '全部品牌' }} · {{ evidence.filters.category || '全部类目' }}<span v-if="evidence.filters.keyword"> · 商品包含“{{ evidence.filters.keyword }}”</span> · {{ evidence.coverage.available_days }} / {{ evidence.coverage.expected_days }} 天有数据</p>
      <div class="answer-kpis"><div><span>本期{{ label }}</span><strong>{{ format(evidence.summary[metric]) }}<small>{{ metricUnit(metric) }}</small></strong></div><div v-for="c in comparisons" :key="c.key"><span>{{ c.name }}比较</span><strong :class="{ negative: c.rates[metric] < 0 }">{{ percent(c.rates[metric]) }}</strong><small>{{ c.coverage.start }} 至 {{ c.coverage.end }} · {{ c.coverage.available_days }} / {{ c.coverage.expected_days }} 天</small></div></div>
      <button v-if="compact" class="chart-toggle" @click="showCharts = !showCharts">{{ showCharts ? '收起图表' : '查看同期对照与每日趋势图' }}</button>
      <div v-if="showCharts" class="answer-charts"><section><h4>{{ label }} · 同期对照</h4><VChart :option="comparisonOption(evidence, label)" autoresize class="chart" /><p>缺数时显示已有数据，灰色表示对比期间不完整；无数据不绘制柱形。</p></section><section><h4>按日{{ label }}趋势</h4><VChart :option="trendOption(evidence, label)" autoresize class="chart" /></section></div>
      <section class="analysis"><h4>分析解读</h4><p>{{ narrative.analysis }}</p></section>
      <div class="narrative-grid"><section v-if="narrative.hypotheses.length" class="hypotheses"><h4>可能原因 · 待验证</h4><ul><li v-for="(h, i) in narrative.hypotheses" :key="i">{{ h }}</li></ul></section><section v-if="narrative.actions.length" class="recommendations"><h4>运营行动建议</h4><ol><li v-for="(a, i) in narrative.actions" :key="i">{{ a }}</li></ol></section></div>
      <details><summary>商品贡献与计算证据</summary><VChart v-if="evidence.ranking.length" :option="rankingOption(evidence.ranking, metric, label, evidence.filters.group, 5)" autoresize class="rank-chart" /><el-table :data="Object.entries(evidence.summary).filter(([k]) => metrics[k]).map(([k, v]) => ({ metric: metrics[k], value: v }))"><el-table-column prop="metric" label="指标" /><el-table-column label="本期数值"><template #default="{ row }">{{ format(row.value) }}</template></el-table-column></el-table><el-table :data="comparisons"><el-table-column prop="name" label="对比" /><el-table-column label="对比区间"><template #default="{ row }">{{ row.coverage.start }} 至 {{ row.coverage.end }}</template></el-table-column><el-table-column :label="label"><template #default="{ row }">{{ format(row.summary[metric]) }}</template></el-table-column><el-table-column label="变化"><template #default="{ row }">{{ percent(row.rates[metric]) }}</template></el-table-column></el-table><p class="note">{{ evidence.note }}</p><p v-for="source in evidence.sources" :key="source.filename" class="source">{{ source.filename }} · {{ source.rows }} 行 · 原表行 {{ source.first_row }}–{{ source.last_row }}</p></details>
    </template>
    <p v-else class="plain-answer">{{ message.answer }}</p>
  </article>
</template>

<style scoped>
.response{margin:24px 0;border:1px solid light-dark(#e2e8f0, var(--border-color));border-radius:14px;background:light-dark(white, var(--app-surface));overflow:hidden;padding:22px}.question{display:flex;gap:12px;align-items:center;border-bottom:1px solid light-dark(#edf2f7, var(--border-color));padding-bottom:18px;margin-bottom:20px}.question h3{font-size:16px;line-height:1.7;margin:0}.avatar{width:32px;height:32px;border-radius:9px;background:#0f766e;color:white;display:inline-flex;align-items:center;justify-content:center;font-size:12px;flex:none}.avatar.user{background:light-dark(#e0e7ff, rgba(96, 165, 250, .12));color:light-dark(#4338ca, #93c5fd)}.response-head{display:flex;align-items:center;gap:10px;font-size:14px}.response-scope,p.note,p.source{font-size:12px;color:light-dark(#64748b, var(--text-secondary));line-height:1.8}.answer-kpis{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:20px 0}.answer-kpis>div{display:flex;flex-direction:column;gap:9px;background:light-dark(#f8fafc, var(--app-surface-2));border-radius:10px;padding:18px}.answer-kpis span,.answer-kpis small{font-size:12px;color:light-dark(#64748b, var(--text-secondary))}.answer-kpis strong{font-size:25px;color:light-dark(#0f766e, var(--text-accent))}.answer-kpis strong small{margin-left:8px;font-weight:400}.answer-kpis .negative{color:light-dark(#c2410c, #fb923c)}.answer-charts,.narrative-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.answer-charts>section{border:1px solid light-dark(#edf2f7, var(--border-color));border-radius:10px;padding:14px}.answer-charts p{font-size:11px;color:light-dark(#94a3b8, var(--text-secondary))}h4{margin:8px 0 12px;font-size:14px}.chart{height:265px}.rank-chart{height:320px}.analysis{margin:22px 0}.analysis p,.plain-answer{white-space:pre-wrap;line-height:1.9;font-size:14px}.hypotheses,.recommendations{border-radius:10px;padding:18px;background:light-dark(#fffbeb, rgba(251, 191, 36, .12))}.recommendations{background:light-dark(#f0fdfa, var(--primary-surface-2))}.narrative-grid ul,.narrative-grid ol{padding-left:20px;margin:0}.narrative-grid li{font-size:13px;line-height:1.9;margin:8px 0}details{margin-top:22px;border-top:1px solid light-dark(#edf2f7, var(--border-color));padding-top:18px}summary{cursor:pointer;color:light-dark(#0f766e, var(--text-accent));font-size:13px}.source{overflow-wrap:anywhere}@media(max-width:1000px){.answer-charts,.narrative-grid{grid-template-columns:1fr}.answer-kpis{grid-template-columns:1fr}}
.compact{border:0;padding:0;margin:0;background:transparent}.compact .response-head{font-size:13px}.compact .avatar{width:27px;height:27px;border-radius:50%;font-size:10px}.compact .answer-kpis{gap:1px;background:light-dark(#e9edf0, var(--app-surface-2));border:1px solid light-dark(#e9edf0, var(--border-color));border-radius:10px;overflow:hidden;margin:17px 0}.compact .answer-kpis>div{border-radius:0;background:light-dark(#fff, var(--app-surface));padding:14px;gap:8px}.compact .answer-kpis strong{font-size:21px}.compact .answer-kpis span,.compact .answer-kpis small{font-size:10px}.compact .analysis p{font-size:14px}.compact .narrative-grid{grid-template-columns:1fr;gap:15px}.compact .hypotheses,.compact .recommendations{background:transparent;padding:0}.compact .narrative-grid li{font-size:13px;margin:6px 0}.compact details{padding-top:15px;margin-top:18px}.chart-toggle{border:0;background:none;color:light-dark(#0f766e, var(--text-accent));font:inherit;font-size:12px;padding:0 0 15px;cursor:pointer}.compact .answer-charts{grid-template-columns:1fr}.compact .response-scope{font-size:10px}@media(max-width:650px){.compact .answer-kpis{grid-template-columns:1fr}}
.understood{font-size:11px;color:light-dark(#8a949f, var(--text-secondary));margin:10px 0 18px}.report-highlights{display:grid;grid-template-columns:repeat(auto-fit,minmax(185px,1fr));gap:1px;background:light-dark(#e7ebee, var(--app-surface-2));border:1px solid light-dark(#e7ebee, var(--border-color));border-radius:12px;overflow:hidden;margin:18px 0 24px}.report-highlights article{background:light-dark(#fff, var(--app-surface));padding:16px;display:flex;flex-direction:column;gap:8px}.report-highlights span,.report-highlights small{font-size:11px;color:light-dark(#7c8793, var(--text-secondary))}.report-highlights strong{font-size:17px;line-height:1.45;color:light-dark(#0f766e, var(--text-accent));overflow-wrap:anywhere}.report-section{margin:25px 0}.report-section.direct{border-left:3px solid #0f766e;padding:4px 0 4px 17px}.report-section h4{font-size:15px}.report-section p,.report-section li,.limitations li{font-size:14px;line-height:1.95;color:light-dark(#303943, var(--text-primary));white-space:pre-wrap}.report-section ul,.limitations ul{padding-left:20px}.report-charts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px;margin:4px 0 22px}.report-charts>section{border:1px solid light-dark(#e7eaee, var(--border-color));border-radius:12px;padding:14px}.report-tables>section{margin:20px 0}.report-tables h4 small{font-weight:400;color:light-dark(#98a1ab, var(--text-secondary));margin-left:10px}.limitations{background:light-dark(#f8fafb, var(--app-surface-2));border-radius:10px;padding:14px 18px;margin-top:20px}.knowledge-sources{margin-top:24px}.knowledge-sources>a{display:block;text-decoration:none;color:light-dark(#334155, var(--text-primary));border:1px solid light-dark(#e7eaee, var(--border-color));border-radius:10px;padding:13px 15px;margin:9px 0}.knowledge-sources>a:hover{border-color:#94b8b0;background:light-dark(#fbfdfc, var(--app-surface-2))}.knowledge-sources span{display:block;font-size:10px;color:light-dark(#98a1aa, var(--text-secondary));margin-top:5px}.knowledge-sources p{font-size:11px;color:light-dark(#6f7a85, var(--text-secondary));line-height:1.7;margin:7px 0 0}.answer-audit p{font-size:11px;color:light-dark(#7e8893, var(--text-secondary));line-height:1.8}@media(max-width:1000px){.report-charts{grid-template-columns:1fr}}@media(max-width:650px){.report-highlights{grid-template-columns:1fr}}
</style>
